    # Prefer staying if no safe better move
    def is_safe(nx, ny):
        if not in_bounds(nx, ny): 
            return False
        if (nx, ny) in obst:
            return False
        # simple line-of-sight avoid proximity to opponent
        if abs(nx - ox) <= 1 and abs(ny - oy) <= 1:
            return False
